arguments.command:
python3 << 'EOF'
import csv
import statistics
from collections import defaultdict

rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

# Focus on Apple, Garmin, Samsung as the 3 brands in the report
target_brands = ['Apple', 'Garmin', 'Samsung']
rows_main = [r for r in rows if r['brand'] in target_brands]
print(f"Main 3 brands: {len(rows_main)} rows")

# Geographic pricing by brand - country median prices
# Focus on countries with enough listings
country_brand_prices = defaultdict(lambda: defaultdict(list))
for r in rows_main:
    try:
        price = float(r['price'])
        country_brand_prices[r['Country']][r['brand']].append(price)
    except:
        pass

print("\n=== COUNTRY-BRAND MEDIAN PRICES (min 5 listings) ===")
country_data = {}
for country, brand_dict in country_brand_prices.items():
    total = sum(len(v) for v in brand_dict.values())
    if total >= 5:
        country_data[country] = {}
        for brand, prices in brand_dict.items():
            if len(prices) >= 3:
                country_data[country][brand] = {
                    'median': round(statistics.median(prices), 2),
                    'mean': round(statistics.mean(prices), 2),
                    'count': len(prices)
                }

for country, bdata in sorted(country_data.items(), key=lambda x: -sum(d['count'] for d in x[1].values())):
    print(f"\n{country}:")
    for brand, stats in bdata.items():
        print(f"  {brand}: median=${stats['median']}, mean=${stats['mean']}, n={stats['count']}")

EOF

